public int[] TwoSum(int[] numbers, int target) {
    int lo = 0, hi = numbers.Length - 1;
    while (lo < hi) {
        int sum = numbers[lo] + numbers[hi];
        if (sum == target) return new[] { lo + 1, hi + 1 }; // one-based indices
        if (sum < target) lo++; else hi--;
    }
    return new int[0];
}

